# Let me look for PWT data on GitHub using a different search approach
curl -s "https://api.github.com/search/repositories?q=penn+world+table+data&sort=updated&per_page=10" --max-time 15 2>/dev/null | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    for item in data.get('items', [])[:10]:
        print(f'{item[\"full_name\"]}: {item.get(\"description\", \"no desc\")}')
except Exception as e:
    print(f'Error: {e}')
" 2>&1

# Check if there's a pwt11 R package
R -e '
# Try to install pwt11 package
tryCatch({
  install.packages("pwt11", repos="https://cloud.r-project.org/", quiet=TRUE)
  cat("pwt11 installed successfully\n")
}, error = function(e) {
  cat("pwt11 package not available\n")
  cat(e$message, "\n")
})

# Also search CRAN for pwt packages
available <- available.packages(repos="https://cloud.r-project.org/")
pwt_pkgs <- available[grep("pwt", tolower(available[,"Package"])),]
if (nrow(pwt_pkgs) > 0) {
  cat("\nAvailable PWT packages on CRAN:\n")
  print(pwt_pkgs[, c("Package", "Version")])
}
' 2>&1
